    """See if minority always works"""
    mismatches = []
    for oi in range(len(output_grid)):
        for oj in range(len(output_grid[0])):
            h, w = 3, 3
            counts = Counter()
            for dy in range(h):
                for dx in range(w):
                    by, bx = oi*3 + dy, oj*3 + dx
                    counts[input_grid[by][bx]] += 1

            if len(counts) == 1:
                mode_val = list(counts.keys())[0]
            else:
                min_count = min(counts.values())
                minority_vals = [v for v, c in counts.items() if c == min_count]
                # Take smallest minority value for tie-breaking
                mode_val = min(minority_vals)

            if mode_val != output_grid[oi][oj]:
                mismatches.append((oi, oj, counts, output_grid[oi][oj], mode_val))
    return mismatches

