input_grid = demo_data[0]["input"]
output_grid = demo_data[0]["output"]

def transform(grid):
    """3x3 downsample with special rule for 5"""
    h, w = len(grid), len(grid[0])
    oh, ow = h // 3, w // 3
    result = []
    for oi in range(oh):
        row = []
        for oj in range(ow):
            counts = Counter()
            for dy in range(3):
                for dx in range(3):
                    by, bx = oi*3 + dy, oj*3 + dx
                    counts[grid[by][bx]] += 1

            if len(counts) == 1:
                mode_val = list(counts.keys())[0]
            else:
                minority_count = min(counts.values())
                minority_vals = [v for v, c in counts.items() if c == minority_count]
                majority_count = max(counts.values())
                majority_vals = [v for v, c in counts.items() if c == majority_count]

                if 5 in minority_vals:
                    # 5 is minority -> output majority value
                    mode_val = minority_vals[0]  # Just use any minority (might be just 5 or include 5)
                else:
                    # 5 is not minority -> output min non-5 minority value
                    non5_minor = [v for v in minority_vals if v != 5]
                    mode_val = min(non5_minor)
                if mode_val is None:
                    mode_val = max(majority_vals)  # fallback

            if mode_val not in counts:
                mode_val = max(counts, key=counts.get)

            row.append(mode_val)
        result.append(row)
    return result

